            new Quote { Id = "https://nl.wikiquote.org/wiki/Louis_Couperus", Text = "Enfin, dat scharrelen met geld zal ik wel tot mijn dood moeten doen, denk ik.", Author = "Louis Couperus" },
            new Quote { Id = "https://nl.wikiquote.org/wiki/Louis_Couperus", Text = "Ik ben ervan overtuigd dat binnen niet al te lange tijd, laat ons zeggen, binnen een eeuw, er geen romans meer zullen worden geschreven.", Author = "Louis Couperus" },
            new Quote { Id = "https://nl.wikiquote.org/wiki/Louis_Couperus", Text = "Beste vriend, een prospectus zou ik gaarne voor je willen schrijven als ik wist wat er in te zeggen. Maar ik kan heusch zo moeilijk reclame voor mijzelven maken. Misschien kun je zelve iets opstellen …", Author = "Louis Couperus" },
            new Quote { Id = "https://nl.wikiquote.org/wiki/Louis_Couperus", Text = "Zoo ik ièts ben, ben ik een Hagenaar.", Author = "Louis Couperus" },
            new Quote { Id = "https://nl.wikiquote.org/wiki/Louis_Couperus", Text = "De Stille kracht geeft vooral weêr de geheimzinnige vijandschap van Javaanschen grond en sfeer en ziel, tegen den Nederlandschen veroveraar. Deze vaak verborgen hostiliteit is een mystiek element in het boek.", Author = "Louis Couperus" },
            new Quote { Id = "https://nl.wikiquote.org/wiki/Louis_Couperus", Text = "Wat ware het heerlijk geweest innig gelukkig als vrienden steeds samen te zijn, steeds samen te leven in een kalm kuis blauw van broederlijkheid, in de gouden extase hunner sympathie, zonder vrouwen...", Author = "Louis Couperus" },
            new Quote { Id = "https://nl.wikiquote.org/wiki/Louis_Couperus", Text = "O ik bid je, gelóof toch, dat niet alles egoïsme in me is, en dat ik veel, zielsveel van je hou, zoveel als een man bijna nooit van een andere man houdt, omdat je zo goed voor me was...", Author = "Louis Couperus" },
            new Quote { Id = "https://nl.wikiquote.org/wiki/Louis_Couperus", Text = "Eigenlijk is het leven toch één zelfbedrog, één dwalen in illusie, dacht zij droef, melancholiek. Een groot doel, een werelddoel of een klein doel voor zichzelf, voor zijn eigen lijf en ziel. O God, wat is dat alles weinig! En wat dwalen wij rond, zonder iets te weten. En elk zoekt zijn eigen doeltje, zijn illusie.", Author = "Louis Couperus" },
            new Quote { Id = "https://nl.wikiquote.org/wiki/Louis_Couperus", Text = "Het stortregende en Dorine van Lowe was doodmoe, toen zij, die middag, vóor het diner nog even bij Karel en Cateau aanwipte, maar Dorine was tevreden over zich-zelve. Zij was na de lunch dadelijk uitgegaan en had geheel Den Haag doortrippeld en doortramd; zij had veel bereikt zo niet alles en haar vermoeide gezicht stond heel blij en haar levendige zwarte ogen flonkerden.", Author = "Louis Couperus" },
            new Quote { Id = "https://nl.wikiquote.org/wiki/Louis_Couperus", Text = "Dàt was een prachtig diner geweest, dat diner dat zij gegeven had, het kostte dan ook duur.", Author = "Louis Couperus" },
            new Quote { Id = "https://nl.wikiquote.org/wiki/Louis_Couperus", Text = "Als een visioen, álle de jaren van zijn leven, had hij het Ding weer zien oprijzen, het vreselijke Ding, dat daar gebaard en geboren was, in die nacht, toen hij, zeker wat koortsig, niet had kunnen slapen, onder de pletterzwarte nacht, die de regen nog omhoog hield, in sterke zeilen, die niet barsten konden, en geen ademhaling doorlieten. Het visioen, neen het Ding, het werkelijke Ding....", Author = "Louis Couperus" },
            new Quote { Id = "https://nl.wikiquote.org/wiki/Louis_Couperus", Text = "Ik reis altijd met pauweveêren: hunne prachtige kleuren brengen geluk aan, o lezer: geloof niet, wie u zegt, dat pauweveêren ongeluk aan brengen!", Author = "Louis Couperus" },
            new Quote { Id = "https://nl.wikiquote.org/wiki/Louis_Couperus", Text = "Onze vreemde nostalgieën dwingen ons telkens andere horizonnen op te roepen rondom onze ziel, die smacht, naar iets, dat zij zelve niet zeggen kan.", Author = "Louis Couperus" },
            new Quote { Id = "https://nl.wikiquote.org/wiki/Louis_Couperus", Text = "Wij, Nederlanders, zijn een vreemd volk. Men moet ons goed kennen, om ons te beminnen, want bijna al onze deugden hebben eene medaille-weêrzijde en deze is het, die vooral den vreemdeling treft. Zoo is onze degelijkheid aan hare weêrzijde zwaarwichtig en vervelend en zo is onze ernst allemachtig saai aan die zijde. Geestig zijn wij niet; humor hebben wij nooit; wij zijn altijd plomp en nooit elegant en daarbij hebben wij een leelijke taal en geen litteratuur.", Author = "Louis Couperus" },
        };
